package com.alpharip.staffmod.AuditFindingsBoard; public final class AuditFindingAction { private final String id,text,assignee;private final long createdAt;private boolean completed;private long completedAt;public AuditFindingAction(String id,String t,String a,long at){if(id==null||id.trim().isEmpty()||t==null||t.trim().isEmpty())throw new IllegalArgumentException("Action ID and text are required");this.id=id;text=t.trim();assignee=a==null?"":a.trim();createdAt=Math.max(0L,at);}public String getId(){return id;}public String getText(){return text;}public String getAssignee(){return assignee;}public long getCreatedAt(){return createdAt;}public boolean isCompleted(){return completed;}public long getCompletedAt(){return completedAt;}public void setCompleted(boolean v,long at){completed=v;completedAt=v?Math.max(0L,at):0L;} }
